CREATE OR REPLACE FUNCTION change_table_owner(table_name TEXT, schema_name TEXT, new_owner TEXT) RETURNS VOID AS $$
DECLARE
    AUTHORIZED_ROLES TEXT[] := ARRAY['postgres', 'admin'];
BEGIN
    IF new_owner = ANY(AUTHORIZED_ROLES) THEN
        EXECUTE format('ALTER TABLE %I.%I OWNER TO %I', schema_name, table_name, new_owner);
    ELSE
        RAISE EXCEPTION 'Unauthorized role: %', new_owner;
    END IF;
END;
$$ LANGUAGE plpgsql;

